```json
{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT regexp_extract(message,'\"msg\":\"([^\"]*)\"',1) emsg, regexp_extract(message,'\"uri\":\"([^\"]*)\"',1) uri, count(*) n, min(time) t0, max(time) t1 FROM abnormal_logs WHERE service_name='ts-ui-dashboard' AND level='ERROR' GROUP BY ALL ORDER BY n DESC",
          "claim": "ts-ui-dashboard's /routeservice/routes proxy calls fail with 'dial tcp 10.108.144.64:8080: i/o timeout' and 502 status."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/routeservice/routes' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Every abnormal /routes request in ts-ui-dashboard takes about 3 s and has no child spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT src, count(*) n, min(time) first_t, max(time) last_t FROM (SELECT 'norm' src,* FROM normal_traces UNION ALL SELECT 'abn',* FROM abnormal_traces) WHERE service_name='ts-route-service' AND attr_span_kind='Server' GROUP BY src",
          "claim": "ts-route-service server spans stop at about 13:21:03 in the abnormal window and never resume."
        },
        {
          "kind": "metric",
          "sql": "SELECT src, metric, attr_source, attr_destination, round(sum(value),1) total FROM (SELECT 'norm' src,* FROM normal_metrics_sum UNION ALL SELECT 'abn',* FROM abnormal_metrics_sum) WHERE metric='hubble_flows_processed_total' AND ((attr_source LIKE '%ui-dashboard%' AND attr_destination LIKE '%route-service%') OR (attr_source LIKE '%route-service%' AND attr_destination LIKE '%ui-dashboard%')) GROUP BY ALL ORDER BY attr_source, src",
          "claim": "Dashboard-to-route flows roughly double while route-to-dashboard flows rise about 30%, with no drops recorded."
        },
        {
          "kind": "metric",
          "sql": "SELECT src, metric, round(avg(value),2) avg_v FROM (SELECT 'norm' src,* FROM normal_metrics UNION ALL SELECT 'abn',* FROM abnormal_metrics) WHERE service_name='ts-route-service' AND metric='container.cpu.usage' GROUP BY ALL",
          "claim": "ts-route-service container CPU falls from about 0.3 to 0.0 while its pod stays running, with no restarts."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','loadgenerator') AND span_name LIKE '%routeservice/routes%' GROUP BY ALL",
          "claim": "Route-listing requests through ts-ui-dashboard fail or take about 3 s, while ts-route-service serves no such spans."
        }
      ]
    }
  ]
}
```

